"""Word documents (DOCX): paragraphs and tables in document order."""

import io

from docx import Document
from docx.table import Table
from docx.text.paragraph import Paragraph

from alloq_offer.workshop.extraction.models import (
    KIND_PARAGRAPH,
    KIND_TABLE,
    ExtractedBlock,
    ExtractionError,
    ExtractionResult,
)


def _table_text(table: Table) -> str:
    rows = (" | ".join(cell.text.strip() for cell in row.cells) for row in table.rows)
    return "\n".join(rows)


def parse_docx(data: bytes) -> ExtractionResult:
    try:
        document = Document(io.BytesIO(data))
    except Exception as exc:  # noqa: BLE001 - python-docx raises many types
        raise ExtractionError("Das Word-Dokument konnte nicht gelesen werden.") from exc
    blocks: list[ExtractedBlock] = []
    paragraphs = tables = 0
    for child in document.element.body.iterchildren():
        if child.tag.endswith("}p"):
            paragraphs += 1
            text = Paragraph(child, document).text.strip()
            if text:
                blocks.append(
                    ExtractedBlock(KIND_PARAGRAPH, text, {"paragraph": paragraphs})
                )
        elif child.tag.endswith("}tbl"):
            tables += 1
            text = _table_text(Table(child, document))
            if text.strip():
                blocks.append(ExtractedBlock(KIND_TABLE, text, {"table": tables}))
    return ExtractionResult(blocks=blocks)
EOF
cat > pdf.py <<'EOF'
"""PDF files with a text layer; pages without one are reported as gaps."""

import io

from pypdf import PdfReader

from alloq_offer.workshop.extraction.models import (
    KIND_PARAGRAPH,
    ExtractedBlock,
    ExtractionError,
    ExtractionResult,
    gap,
)

NO_TEXT_LAYER = "OCR nötig"


def parse_pdf(data: bytes) -> ExtractionResult:
    try:
        reader = PdfReader(io.BytesIO(data))
        if reader.is_encrypted:
            raise ExtractionError("Die PDF-Datei ist passwortgeschützt.")
        pages = [(page.extract_text() or "").strip() for page in reader.pages]
    except ExtractionError:
        raise
    except Exception as exc:  # noqa: BLE001 - pypdf raises many types
        raise ExtractionError("Die PDF-Datei konnte nicht gelesen werden.") from exc
    blocks = [
        ExtractedBlock(KIND_PARAGRAPH, text, {"page": number})
        if text
        else gap(NO_TEXT_LAYER, {"page": number})
        for number, text in enumerate(pages, 1)
    ]
    return ExtractionResult(blocks=blocks)
